private def finalize_success : Nil
  @was_process_successful = true
  @deactivated_user_account = @target_user_account
end

private def send_digest_email_to_each_recipient : Nil
  @list_of_digest_recipients.each do |recipient|
    DigestMailer.weekly_digest(user: recipient).deliver_later
    @count_of_digest_emails_sent += 1
  end
end
